<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {ElMessage,type FormInstance} from 'element-plus'
import type {Row} from '../api/types'
import {post,put} from '../api/http'
import {useAuth} from '../stores/auth'
import {useResource,useMutation} from '../composables/useResource'
import {navigation} from '../router'
import PageHeader from '../components/PageHeader.vue'
import ResourceState from '../components/ResourceState.vue'
import DataTable from '../components/DataTable.vue'
import EntityDialog,{type Field} from '../components/EntityDialog.vue'
const auth=useAuth(),tab=ref('users')
const users=useResource<Row[]>('/admin/users',[]),roles=useResource<Row[]>('/admin/roles',[]),dictionaries=useResource<Row[]>('/admin/dictionaries',[]),audit=useResource<Row[]>('/audit-logs',[])
const {saving,run}=useMutation(async()=>{await Promise.all([reload(),auth.refresh()])})
async function reload(){await Promise.all([users.load(),roles.load(),dictionaries.load(),audit.load()])}
const userOpen=ref(false),userRef=ref<FormInstance>(),editingUser=ref<Row>(),userForm=reactive<Record<string,any>>({})
const self=computed(()=>editingUser.value?.id===auth.user?.id)
function editUser(row?:Row){editingUser.value=row;Object.assign(userForm,{username:row?.username||'',name:row?.name||'',role_id:row?.role_id||'',enabled:row?Boolean(row.enabled):true,password:''});userOpen.value=true}
async function saveUser(){if(!await userRef.value?.validate().catch(()=>false))return;const payload={...userForm};if(!payload.password)delete payload.password;else if(payload.password.length<8||new TextEncoder().encode(payload.password).length>72){ElMessage.warning('密码应至少8个字符，且不超过72字节');return}if(await run(()=>editingUser.value?put(`/admin/users/${editingUser.value.id}`,payload):post('/admin/users',payload),'账号已保存'))userOpen.value=false}
const roleOpen=ref(false),editingRole=ref<Row>(),permissions=ref<string[]>([]),menus=ref<string[]>([])
const permissionOptions=[['*','全部业务权限'],['dashboard:read','查看驾驶舱'],['project:read','查看项目'],['project:write','维护项目'],['master:read','查看基础档案'],['master:write','维护基础档案'],['request:read','查看采购申请'],['request:write','创建与提交申请'],['request:approve','审批采购申请'],['quote:read','查看供应商报价'],['quote:write','维护询价报价'],['order:read','查看采购订单'],['order:write','下单与取消订单'],['order:receive','验收入库'],['inventory:read','查看项目范围库存流水'],['inventory:company','查看公司共享仓库'],['stocktake:read','查看盘点'],['stocktake:write','维护盘点草稿'],['stocktake:approve','独立审核盘点'],['inventory:issue','项目领料出库'],['cost:read','查看成本费用'],['cost:write','登记成本费用'],['contract:read','查看合同'],['contract:write','维护合同附件'],['contract:plan','维护付款阶段计划'],['finance:read','查看财务'],['finance:write','申请与执行付款、登记退款'],['finance:approve','审批付款申请'],['finance:record','直接登记付款'],['system:manage','管理系统设置']]
const menuOptions=navigation.filter(n=>n.key!=='quotes').map(n=>({key:n.key,label:n.label})).concat([{key:'users',label:'账号子菜单'},{key:'roles',label:'角色子菜单'},{key:'company',label:'品牌子菜单'},{key:'dictionaries',label:'字典子菜单'},{key:'audit',label:'审计子菜单'},{key:'admin',label:'管理菜单'},{key:'payables',label:'应付子菜单'},{key:'payments',label:'付款子菜单'},{key:'payment-applications',label:'付款申请子菜单'},{key:'stock-movements',label:'库存流水子菜单'},{key:'audit-logs',label:'审计日志子菜单'}])
function editRole(row:Row){editingRole.value=row;permissions.value=[...(row.permissions||[])];menus.value=[...(row.menus||[])];roleOpen.value=true}
async function saveRole(){if(await run(()=>put(`/admin/roles/${editingRole.value!.id}`,{permissions:permissions.value,menus:menus.value}),'角色权限已保存，将按最新授权访问'))roleOpen.value=false}
const brand=reactive({name:'',system_name:'',theme_color:'#2563eb'}),brandRef=ref<FormInstance>()
watch(()=>auth.company,value=>Object.assign(brand,value),{immediate:true})
async function saveBrand(){if(!await brandRef.value?.validate().catch(()=>false))return;if(await run(()=>put('/admin/company',{name:brand.name,system_name:brand.system_name,theme_color:brand.theme_color}),'品牌设置已生效'))auth.applyBrand()}
const dictionaryOpen=ref(false),selectedDictionary=ref<Row>()
const dictionaryFields:Field[]=[{key:'label',label:'显示名称',required:true},{key:'value',label:'字典值',required:true},{key:'sort_order',label:'排序',kind:'number',min:0,max:100000,required:true}]
</script>
<template>
<PageHeader title="系统管理" subtitle="维护企业账号、角色权限与品牌配置，操作记录可追溯。"><el-button :loading="users.loading.value||roles.loading.value" @click="reload">刷新</el-button></PageHeader>
<section class="panel table-panel"><el-tabs v-model="tab">
<el-tab-pane label="账号管理" name="users"><ResourceState :loading="users.loading.value" :error="users.error.value" @retry="users.load"><DataTable :rows="users.data.value" :action-width="110" :columns="[{key:'username',label:'登录账号',minWidth:160},{key:'name',label:'姓名'},{key:'role_name',label:'所属角色',minWidth:150},{key:'enabled',label:'账号状态'}]"><template #toolbar><el-button type="primary" @click="editUser()">＋ 新增账号</el-button></template><template #enabled="{row}"><el-tag :type="row.enabled?'success':'info'" effect="light">{{row.enabled?'启用':'停用'}}</el-tag></template><template #actions="{row}"><el-button link type="primary" @click="editUser(row)">维护</el-button></template></DataTable></ResourceState></el-tab-pane>
<el-tab-pane label="角色与权限" name="roles"><div class="notice-strip">授权规则 <span>菜单可见性与操作权限同时生效，服务端对每次请求再次校验。</span></div><ResourceState :loading="roles.loading.value" :error="roles.error.value" @retry="roles.load"><DataTable :rows="roles.data.value" :action-width="130" :columns="[{key:'name',label:'角色名称'},{key:'code',label:'角色标识'},{key:'permissions',label:'业务权限',minWidth:200},{key:'menus',label:'可访问菜单',minWidth:220}]"><template #permissions="{row}">{{row.permissions.includes('*')?'全部业务权限':`${row.permissions.length} 项权限`}}</template><template #menus="{row}">{{row.menus.length}} 项菜单</template><template #actions="{row}"><el-button link type="primary" @click="editRole(row)">配置权限</el-button></template></DataTable></ResourceState></el-tab-pane>
<el-tab-pane label="企业与品牌" name="brand"><div class="settings-layout"><el-form ref="brandRef" :model="brand" label-position="top" class="settings-form"><el-form-item label="企业名称" prop="name" :rules="[{required:true,message:'请输入企业名称'}]"><el-input v-model="brand.name" maxlength="160"/></el-form-item><el-form-item label="系统名称" prop="system_name" :rules="[{required:true,message:'请输入系统名称'}]"><el-input v-model="brand.system_name" maxlength="80"/></el-form-item><el-form-item label="品牌强调色" prop="theme_color" :rules="[{pattern:/^#[0-9a-fA-F]{6}$/,message:'请输入六位十六进制颜色'}]"><div class="inline-control"><el-color-picker v-model="brand.theme_color"/><el-input v-model="brand.theme_color" maxlength="7"/></div></el-form-item><el-button type="primary" :loading="saving" @click="saveBrand">保存品牌配置</el-button></el-form><div class="brand-preview"><span class="eyebrow">品牌预览</span><div class="brand-preview-mark" :style="{background:brand.theme_color}">筑</div><h2>{{brand.system_name||'系统名称'}}</h2><p>{{brand.name||'企业名称'}}</p></div></div></el-tab-pane>
<el-tab-pane label="数据字典" name="dictionaries"><ResourceState :loading="dictionaries.loading.value" :error="dictionaries.error.value" @retry="dictionaries.load"><DataTable :rows="dictionaries.data.value" :action-width="100" :columns="[{key:'category',label:'分类',minWidth:160},{key:'label',label:'显示名称'},{key:'value',label:'字典值',minWidth:160},{key:'sort_order',label:'排序',width:100}]"><template #actions="{row}"><el-button link type="primary" @click="selectedDictionary=row;dictionaryOpen=true">编辑</el-button></template></DataTable></ResourceState></el-tab-pane>
<el-tab-pane label="操作审计" name="audit"><ResourceState :loading="audit.loading.value" :error="audit.error.value" @retry="audit.load"><DataTable :rows="audit.data.value" :columns="[{key:'created_at',label:'操作时间',date:true,minWidth:180},{key:'operator_name',label:'操作人'},{key:'action',label:'动作'},{key:'entity_type',label:'业务对象'},{key:'entity_id',label:'对象编号'},{key:'detail',label:'操作说明',minWidth:240}]"/></ResourceState><p class="field-hint">展示服务端最近 500 条操作记录。</p></el-tab-pane>
</el-tabs></section>
<el-dialog v-model="userOpen" :title="editingUser?'维护账号':'新增账号'" width="600px" destroy-on-close :close-on-click-modal="false"><el-form ref="userRef" :model="userForm" label-position="top"><div class="form-grid"><el-form-item label="登录账号" prop="username" :rules="[{required:true,message:'请输入登录账号'},{pattern:/^[A-Za-z0-9_.@-]{1,60}$/,message:'仅支持字母、数字、下划线、点、@ 和短横线'}]"><el-input v-model="userForm.username"/></el-form-item><el-form-item label="姓名" prop="name" :rules="[{required:true,message:'请输入姓名'}]"><el-input v-model="userForm.name" maxlength="60"/></el-form-item><el-form-item label="角色" prop="role_id" :rules="[{required:true,message:'请选择角色'}]"><el-select v-model="userForm.role_id" :disabled="self"><el-option v-for="r in roles.data.value" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="账号状态"><el-switch v-model="userForm.enabled" :disabled="self" active-text="启用" inactive-text="停用"/></el-form-item><el-form-item :label="editingUser?'重置密码（留空保留）':'登录密码'" prop="password" class="full-width" :rules="editingUser?[]:[{required:true,message:'请输入登录密码'}]"><el-input v-model="userForm.password" type="password" show-password autocomplete="new-password"/><span class="field-hint">至少8个字符，不超过72字节。重置密码后，该账号需要重新登录。</span></el-form-item></div></el-form><template #footer><el-button @click="userOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveUser">保存账号</el-button></template></el-dialog>
<el-dialog v-model="roleOpen" :title="`角色权限 · ${editingRole?.name||''}`" width="820px" :close-on-click-modal="false"><h3>业务操作权限</h3><el-checkbox-group v-model="permissions" class="permission-grid"><el-checkbox v-for="[value,label] in permissionOptions" :key="value" :value="value">{{label}}</el-checkbox></el-checkbox-group><el-divider/><h3>可访问菜单</h3><p class="field-hint">询比价使用采购申请菜单授权。选中菜单后，还需对应业务权限。</p><el-checkbox-group v-model="menus" class="permission-grid"><el-checkbox v-for="m in menuOptions" :key="m.key" :value="m.key">{{m.label}}</el-checkbox></el-checkbox-group><template #footer><el-button @click="roleOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRole">保存授权</el-button></template></el-dialog>
<EntityDialog v-model="dictionaryOpen" title="维护字典" :endpoint="`/admin/dictionaries`" :record="selectedDictionary" :fields="dictionaryFields" @saved="reload"/>
</template>
